using System.Reflection;
using System.Text.Json;
using g0v0.Server.Common.Database.Models;
using g0v0.Server.Common.Rulesets;
using g0v0.Server.Stable.Services;
using osu.Game.IO.Legacy;
using osu.Game.Rulesets.Scoring;

namespace g0v0.Server.Stable.Tests.Services;

public class StableScoreSubmissionTests
{
    [Test]
    public void DecryptsBpyGenerated256BitRijndaelFixtureAndVerifiesItsChecksum()
    {
        // Fixture generated by bpy app/encryption.py with counts from its score_submission_test.py::_score.
        Dictionary<string, string> fixture = Fixture();
        string plaintext = StableScoreSubmission.Decrypt(fixture["encrypted"], fixture["iv"], fixture["version"]);
        string clientHash = StableScoreSubmission.Decrypt(fixture["encryptedClientHash"], fixture["iv"], fixture["version"]);
        StableScoreSubmission submission = StableScoreSubmission.Parse(plaintext);
        Assert.Multiple(() =>
        {
            Assert.That(plaintext, Is.EqualTo(fixture["plaintext"]));
            Assert.That(clientHash, Is.EqualTo(fixture["clientHash"]));
            Assert.That(submission.Username, Is.EqualTo("peppy"));
            Assert.That(submission.VerifyChecksum("peppy", fixture["version"], clientHash, fixture["storyboardHash"]), Is.True);
            Assert.That(submission.VerifyChecksum("other", fixture["version"], clientHash, fixture["storyboardHash"]), Is.False);
        });
    }

    [Test]
    public void ToleratesTheClientsTrailingClientFlagsField()
    {
        Dictionary<string, string> fixture = Fixture();

        // The live client appends one more colon-delimited field (its internal client flags), so a
        // strict eighteen-field check would reject every real submission with "error: no".
        string plaintext = fixture["plaintext"] + ":26685362";
        StableScoreSubmission submission = StableScoreSubmission.Parse(plaintext);

        Assert.Multiple(() =>
        {
            Assert.That(submission.Username, Is.EqualTo("peppy"));
            Assert.That(submission.Mode, Is.Zero);
            Assert.That(submission.VerifyChecksum("peppy", fixture["version"], fixture["clientHash"], fixture["storyboardHash"]), Is.True);
        });
    }

    [Test]
    public void RejectsAPayloadWithTooFewFields()
    {
        Assert.That(
            () => StableScoreSubmission.Parse("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa:peppy:00000000000000000000000000000000"),
            Throws.InstanceOf<FormatException>());
    }

    [TestCase(0, HitResult.Ok, HitResult.Meh, HitResult.Good)]
    [TestCase(1, HitResult.Ok, HitResult.Meh, HitResult.LargeBonus)]
    [TestCase(2, HitResult.LargeTickHit, HitResult.SmallTickHit, HitResult.SmallTickMiss)]
    [TestCase(3, HitResult.Ok, HitResult.Meh, HitResult.Good)]
    public void MapsStableCountersToRulesetStatistics(int mode, HitResult hundred, HitResult fifty, HitResult katu)
    {
        string[] fields = Fixture()["plaintext"].Split(':');
        fields[15] = mode.ToString();
        Score score = StableScoreSubmission.Parse(string.Join(':', fields)).ToScore(new RulesetManager("missing"), 1, 2, "20240102", DateTimeOffset.UtcNow, 1000);
        Assert.Multiple(() =>
        {
            Assert.That(score.Type, Is.EqualTo("stable"));
            Assert.That(score.ClassicTotalScore, Is.EqualTo(26810));
            Assert.That(score.Processed, Is.False);
            Assert.That(score.MaximumStatistics, Is.Empty);
            Assert.That(score.Statistics[HitResult.Great], Is.EqualTo(83));
            Assert.That(score.Statistics[hundred], Is.EqualTo(14));
            Assert.That(score.Statistics.TryGetValue(fifty, out int fiftyCount) ? fiftyCount : 0, Is.EqualTo(mode == 1 ? 0 : 5));
            Assert.That(score.Statistics.TryGetValue(katu, out int katuCount) ? katuCount : 0, Is.EqualTo(mode == 0 ? 0 : mode == 1 ? 29 : 6));
        });
    }

    [Test]
    public void ReplayContainsStableHeaderCompressedPayloadAndOnlineId()
    {
        Dictionary<string, string> fixture = Fixture();
        StableScoreSubmission submission = StableScoreSubmission.Parse(fixture["plaintext"]);
        Score score = submission.ToScore(new RulesetManager("missing"), 1, 2, "20240102", DateTimeOffset.UtcNow, 1000);
        score.Id = 123;
        byte[] frames = [1, 2, 3, 4, 5];
        using MemoryStream stream = new(submission.CreateReplay(score, "peppy", "20240102", frames));
        using SerializationReader reader = new(stream);
        Assert.That(reader.ReadByte(), Is.Zero);
        Assert.That(reader.ReadInt32(), Is.EqualTo(20240102));
        Assert.That(reader.ReadString(), Is.EqualTo(submission.BeatmapChecksum));
        Assert.That(reader.ReadString(), Is.EqualTo("peppy"));
        Assert.That(reader.ReadString(), Has.Length.EqualTo(32));
        Assert.That(Enumerable.Range(0, 6).Select(_ => reader.ReadUInt16()).ToArray(), Is.EqualTo(new ushort[] { 83, 14, 5, 23, 6, 6 }));
        Assert.That(reader.ReadInt32(), Is.EqualTo(26810));
        Assert.That(reader.ReadUInt16(), Is.EqualTo(52));
        Assert.That(reader.ReadBoolean(), Is.False);
        Assert.That(reader.ReadInt32(), Is.EqualTo(136));
        Assert.That(reader.ReadString(), Is.Empty);
        _ = reader.ReadDateTime();
        Assert.That(reader.ReadByteArray(), Is.EqualTo(frames));
        Assert.That(reader.ReadInt64(), Is.EqualTo(123));
        Assert.That(stream.Position, Is.EqualTo(stream.Length));
    }

    internal static Dictionary<string, string> Fixture()
    {
        using Stream stream = Assembly.GetExecutingAssembly().GetManifestResourceStream("g0v0.Server.Stable.Tests.Fixtures.bancho-score.json")!;
        return JsonSerializer.Deserialize<Dictionary<string, string>>(stream)!;
    }
}